const _varsS = Game.vars;
Game.vars = function () { const v = _varsS.call(Game); if (isShip()) v.addr = 'капитан'; return v; };
const SHIP_DTABS = { foreign: 'Флот и связь', social: 'Экипаж', economy: 'Корабль' };
const DTABS_BASE = { ...DECREE_TABS };
const _eraLookS = Game.eraLook;
Game.eraLook = function () {
  _eraLookS.call(Game);
  Object.assign(DECREE_TABS, DTABS_BASE);
  if (!isShip()) return;
  for (const r of Object.keys(ROLES_S)) Object.assign(ROLES[r], ROLES_S[r]);
  Object.assign(STAT_NAMES, { treasury: 'Запасы', swiss: 'Личный трюм', economy: 'Корабль', support: 'Экипаж', army: 'Охрана', fear: 'Дисциплина' });
  Object.assign(DECREE_TABS, SHIP_DTABS);
};
const _bankS = Game.bank;
Game.bank = function () { return isShip() ? { name: 'Личный трюм', short: 'Трюм', to: 'капсулу', at: 'в спасательной капсуле', acc: 'ваш личный трюм в спасательной капсуле', ins: 'личным трюмом', dat: 'личному трюму' } : _bankS.call(Game); };

