  Game.noteDeal('adv:' + role);
  const k = A.comp * [1, 1, 0.6, 0.35, 0.2][Math.min(Game.dealInfo('adv:' + role).n, 4)], r = v => Math.max(1, Math.round(v * k));
  const fx = { defense: { treasury: -4, army: r(7), fac: { hawks: { a: r(4) } } }, economy: { treasury: -6, economy: r(5), fac: { oligarchs: { a: r(3) } } }, police: { fear: r(7), support: -3, fac: { left: { a: -3 } } }, propaganda: { treasury: -4, support: r(5) }, foreign: { treasury: -3, rel: Object.fromEntries(REGIONS[STAR].countries.map(c => [c, r(3)])) } }[role];
  const changes = Game.apply(fx);
