// ---------- финалы ----------
Game.endingHooks.push((type, E, verdicts) => {
  if (!isShip()) return;
  const H = Game.sh();
  const T = {
    exile: ['Спасательная капсула', 'Капсула села на тихой планете. Местные приняли вас за бога, потом за торговца, потом научили копать. У вас огород и ни одного подчинённого. Иногда вы произносите речь. Морковь слушает.'],
    helicopter: ['Спасательная капсула', 'Капсула отстрелилась чисто. Запасов в ней оказалось на удивление много. Вы знаете, почему.'],
    coup: ['Отстранён по статье четырнадцатой', 'Вас заперли в каюте с иллюминатором. Кормят по норме, которую вы сами утвердили. Раз в неделю заходит старпом и докладывает, что корабль идёт по графику. Это обиднее всего: по графику он при вас не шёл.'],
    revolution: ['Высажен', 'Нижние палубы высадили вас на первой же обитаемой планете. С пайком на месяц и портретом: вашим, из каюты. Корабль ушёл. С орбиты вам на прощание мигнули бортовыми огнями. Вы решили считать это салютом.'],
    retired: ['Сдал командование', 'Вы сдали коды, пожали руки мостику и сошли на станции. Корабль ушёл дальше. В баре станции вы рассказываете про одиннадцать тысяч пушистых комочков. Вам не верят.'],
  }[type];
  if (T) { E.title = T[0]; E.text = T[1]; }
  if (type === 'survived') {
    E.title = H.disc >= 14 ? 'Капитан, о котором пишут учебники' : H.viol >= 8 ? 'Гроза Устава' : H.lost >= 25 ? 'Капитан красных комбинезонов' : H.decks >= 4 ? 'Корабль имени себя' : 'Десять лет в кресле';
    E.text = `${Game.endYear() - 1} год. Корабль-сменщик так и не пришёл, но срок вышел, и «Благое намерение» ложится на обратный курс. Вы всё ещё в кресле. `
      + (H.disc >= 14 ? 'Открытий сделано столько, что Штаб выделил под них отдельный архив. Половина названа вашим именем; учёные протестовали, вы настояли.' : H.disc >= 6 ? 'Открытий набралось на добротный отчёт. Штаб его когда-нибудь прочтёт.' : 'С открытиями негусто. В отчёте вы написали «изучен обширный район». Район действительно обширный.')
      + ` Устав нарушен ${H.viol} раз${H.viol === 0 ? ': старпом растерян и ищет подвох' : H.viol >= 8 ? '. Блюстители издали журнал отдельной книгой; она расходится лучше Устава' : '. Старпом вёл счёт'}.`
      + ` Младших сотрудников в красном не вернулось: ${H.lost}.${H.lost >= 25 ? ' В охране служат по жребию.' : H.lost === 0 ? ' Охрана не верит своему счастью и ждёт подвоха.' : ''}`
      + (H.decks ? ` Палуб вашего имени: ${H.decks} из двадцати четырёх.` : '')
      + ' Экипаж говорит, что вы были не худшим капитаном. Другого у них не было, так что это правда.';
  }
  verdicts.length = 0;
  verdicts.push(`Высадок: ${H.done}`); verdicts.push(`Открытий: ${H.disc}`); verdicts.push(`Нарушений Устава: ${H.viol}`); verdicts.push(`Потери в красном: ${H.lost}`);
  if (H.decks) verdicts.push(`Палуб вашего имени: ${H.decks}`);
});

// ---------- палубный листок ----------
const _pressPageS = UI.pressPage;
UI.pressPage = async function (news) {
  if (!isShip()) return _pressPageS.call(UI, news);
  const ch = [], H = Game.sh();
  for (const h of news) { const fx = h.fx ? Game.resolveFx(h.fx) : null; if (fx) ch.push(...Game.apply(fx)); Game.log('Сводка: ' + h.head); }
  const off = [['Курс', H.loc.state === 'orbit' ? `Стоим на орбите: ${PLANETS[H.loc.id].name}.` : `Идём к цели: ${PLANETS[H.loc.id].name}. Ещё ${H.loc.eta} кв.`],
    ['С палуб', pick(['На шестой палубе найден носок. Владельца просят опознать. Носок в карантине.', 'Кружок трёхмерных шашек ищет третьего. Третье измерение имеется.', 'Потерян гаечный ключ на 32. Последний раз видели в реакторе.', 'Столовая сообщает: сегодня каша. Завтра, по прогнозу, тоже.'])],
    ['Объявление', pick(['Запись в иллюзион закрыта до конца квартала. Очередь можно занять в иллюзионе.', 'Служба безопасности набирает добровольцев. Форма выдаётся.', 'Доктор напоминает: он врач, а не справочное бюро. Часы приёма прежние.', 'Капитан выступит с краткой речью. Просьба взять с собой воду и стул.'])]];
  if (!news.length && S.turn % 2) return;
  await Modal.open(`<div class="sh-np">
      <div class="sh-np-mast">Палубный листок</div>
      <div class="sh-np-date">ЗК «Благое намерение» · ${S.q}-й квартал ${S.year} года · выходит, когда работает принтер</div>
      ${news.map((h, i) => `<article class="${i ? '' : 'lead'}"><span class="sh-np-src">Сводка Флота</span><h3>${esc(h.head)}</h3><p>${esc(Game.fmt(h.text))}</p></article>`).join('')}
      <div class="sh-np-off">${off.map(([t, x]) => `<div><b>${esc(t)}</b><p>${esc(x)}</p></div>`).join('')}</div>
      ${ch.length ? `<div class="fx-list">${UI.changes(ch)}</div>` : ''}
    </div>`, news.some(h => Game.histChoice(h)) ? 'Решение капитана?' : 'Дальше', 'wide');
};

// ---------- вкладки ----------
const shBtn = (id, name, cost, ok, free) => `<button class="btn small" data-act="${id}" ${!ok || S.phase !== 'hub' || (!free && S.ap <= 0) ? 'disabled' : ''}>${esc(name)}${cost ? `<small>${esc(cost)}</small>` : ''}</button>`;
const shNum = v => `${v >= 0 ? '+' : '−'}${String(Math.abs(Math.round(v * 10) / 10)).replace('.', ',')}`;
Object.assign(UI, {
  tab_away() {
    const H = Game.sh(), P = PLANETS[H.loc.id], hub = S.phase === 'hub', T = H.team, redMax = Game.shRedMax();
    if (T.red > redMax) T.red = redMax;
    if (!Game.shLeadOk(T.lead)) T.lead = ['cap', ...Object.keys(S.adv)].find(Game.shLeadOk) || 'cap';
    const stars = n => '★'.repeat(n) + '☆'.repeat(5 - n);
    const tally = `<section class="card cr-side"><div class="eyebrow">Журнал экспедиции</div>
        <p class="sh-tally"><span>Высадок <b>${H.done}</b></span><span>Открытий <b>${H.disc}</b></span><span>Нарушений Устава <b>${H.viol}</b></span><span>Потери в красном <b>${H.lost}</b></span></p>
        <p class="muted small">Открытия радуют учёных и Штаб. Нарушения статьи первой злят Блюстителей Устава и рано или поздно доходят до Штаба. Потери в красном считает охрана.</p></section>`;
    if (H.loc.state === 'transit') {
      return `<p class="lede">Корабль идёт к следующей цели. Высадки возможны только на орбите. Пока есть время заняться нормами, мостиком и экипажем.</p>
        <div class="cr"><section class="card" style="flex:1.4"><div class="eyebrow">В пути</div><h2 class="rm-rank">${esc(P.name)}</h2><p class="muted small">${esc(P.kind)} · ходу ещё ${H.loc.eta} кв. · по слухам: ${esc(P.gain)}</p><p>${esc(P.orbit)}</p></section>${tally}</div>`;
    }
    const lead = L => { const ok = Game.shLeadOk(L), sk = L === 'cap' ? CAP_SK[S.regime] : OFF_SK[L], pen = L !== 'cap' && (S.adv[L].relative ? 2 : 0) + (S.adv[L].loy < 35 ? 1 : 0);
      return `<button class="sh-lead ${T.lead === L ? 'on' : ''}" data-act="sht:lead:${L}" ${!ok || !hub ? 'disabled' : ''}><b>${esc(L === 'cap' ? 'Капитан лично' : ROLES[L].title)}</b><span>${L === 'cap' ? esc(S.leader.name) : esc(S.adv[L].name)}</span><small>${ok ? Object.keys(SK_NAME).map(k => `${SK_NAME[k]} ${Math.max(0, sk[k] - (pen || 0))}`).join(' · ') : L === 'cap' ? `ранен, ещё ${H.capHurt} кв.` : `в лазарете, ещё ${H.hurt[L]} кв.`}</small></button>`; };
    const opts = P.opts.map(o => (o[1] ? `<li><b>${SK_NAME[o[1]]}</b> ${stars(o[2])} <span class="muted">сейчас шанс ${Math.round(Game.shChance(o[1], o[2]) * 100)}%</span></li>` : '<li><b>без риска</b> <span class="muted">можно ничего не трогать и уйти</span></li>')).join('');
    return `<p class="lede">Запасы, починку и открытия корабль добывает внизу. Вы решаете, кто ведёт группу и сколько с ней идёт охраны, а на месте — как поступить. Каждый офицер силён в своём: кто-то дерётся, кто-то думает, кто-то договаривается. Капитан может спуститься сам: Устав не советует, традиция требует.</p>
      <div class="cr">
        <section class="card" style="flex:1.4"><div class="eyebrow">На орбите</div><h2 class="rm-rank">${esc(P.name)}</h2><p class="muted small">${esc(P.kind)} · что тут можно найти: ${esc(P.gain)}</p>
          <p>${esc(P.orbit)}</p>
          ${H.loc.done ? '<p><b>Высадка состоялась.</b> Здесь больше нечего делать: проложите курс дальше.</p>' : `<div class="eyebrow mt">Что пригодится внизу</div><ul class="sh-need">${opts}</ul>`}</section>
        ${tally}
      </div>
      ${H.loc.done ? '' : `<section class="card mt"><div class="eyebrow">Группа высадки</div>
        <div class="sh-leads">${['cap', ...Object.keys(S.adv)].map(lead).join('')}</div>
        <div class="sh-red"><span class="br-name">Охрана в красном<span class="muted small">Каждое отделение прибавляет силы и немного страхует в остальном. Если дело сорвётся, платить будут они; без охраны — тот, кто ведёт группу.</span></span>
          <div class="sh-seg">${[0, 1, 2, 3].map(n => `<button class="jp-pos ${T.red === n ? 'on' : ''}" data-act="sht:red:${n}" ${n > redMax || !hub ? 'disabled' : ''}>${['Без охраны', 'Одно', 'Два', 'Три'][n]}</button>`).join('')}</div></div>
        <div class="acts mt">${shBtn('sha:go', 'Начать высадку', 'приказ · решение принимается на месте', true)}</div></section>`}
      <section class="card mt"><div class="eyebrow">Проложить курс</div>
        <p class="muted small">${H.loc.done ? 'Выберите следующую цель. Если не выберете до конца квартала, рулевой решит сам.' : 'Можно уйти и без высадки, но научный отдел этого не простит.'}</p>
        <div class="sh-course">${(H.opts || []).map((o, i) => { const Q = PLANETS[o.id]; return `<button class="sh-lead" data-act="shc:${i}" ${!hub ? 'disabled' : ''}><b>${esc(Q.name)}</b><span>${esc(Q.kind)} · ходу ${o.eta} кв.</span><small>по слухам: ${esc(Q.gain)}${H.used[o.id] ? ' · уже бывали' : ''}</small></button>`; }).join('')}</div></section>`;
  },
  shNorms() {
    const H = Game.sh(), hub = S.phase === 'hub', B = Game.budgetCalc(), fx = Game.shNormFx();
    const row = (k, N) => `<div class="sh-norm"><div class="br-name">${esc(N.name)}<span class="muted small">${esc(N.hint)}</span></div>
        <div class="sh-seg">${N.lv.map((l, i) => `<button class="jp-pos ${H.norm[k] === i ? 'on' : ''}" data-act="shn:${k}:${i}" ${!hub ? 'disabled' : ''}>${esc(l[0])}<small>${l[1] ? shNum(l[1]) : '0'}</small></button>`).join('')}</div>
        <p class="muted small">${esc(N.lv[H.norm[k]][2])}</p></div>`;
    const chip = (name, d) => (Math.abs(d) < 0.05 ? '' : `<span class="fx ${d > 0 ? 'up' : 'down'}"><span>${name}</span><b>${shNum(d)}</b></span>`);
    const F = REGIONS[STAR].factions;
    return `<div class="budget">
      <section class="card"><div class="budget-head"><div class="eyebrow">Корабельные нормы · меняются без приказов</div></div>
        <p class="muted small">Денег на корабле нет. Есть запасы и нормы, по которым они расходуются: сколько есть, сколько спать, что чинить. Сам корабль даёт меньше, чем съедает экипаж; разницу покрывают высадки.</p>
        ${Object.entries(NORMS).map(([k, N]) => row(k, N)).join('')}</section>
      <section class="card budget-side"><div class="eyebrow">Запасы за квартал</div>
        <table class="ledger"><tbody>${B.hookInc.map(h => `<tr><td>${esc(h.label)}</td><td class="num ${h.v >= 0 ? 'pos' : 'neg'}">${shNum(h.v)}</td></tr>`).join('')}
          <tr class="total"><td>Итого</td><td class="num">${shNum(B.net)}</td></tr></tbody></table>
        ${B.palace ? `<p class="muted small">Со стола командования в ваш личный трюм: +${B.palace} ед. за квартал.</p>` : ''}
        <div class="eyebrow mt">Что нормы делают за квартал</div>
        <div class="fx-list">${chip('Экипаж', fx.t.support)}${chip('Корабль', fx.t.economy)}${chip('Охрана', fx.t.army)}${chip('Дисциплина', fx.t.fear)}${Object.entries(fx.f).map(([f, d]) => chip(`${F[f].icon} ${F[f].short}`, d)).join('')}</div>
        ${Object.values(fx.t).concat(Object.values(fx.f)).every(d => Math.abs(d) < 0.05) ? '<p class="muted small">При таких нормах никто не рад и никто не обижен.</p>' : ''}
        <p class="muted small">Сверх этого корабль ветшает в пути, а настроения отделов тянутся к середине. Запасов сейчас: <b>${Math.round(S.treasury)}</b>.</p></section>
    </div>`;
  },
  shBridge() {
    const H = Game.sh(), hub = S.phase === 'hub';
    const card = r => { const A = S.adv[r], Ro = ROLES[r], hurt = H.hurt[r] > 0, sk = OFF_SK[r], pen = (A.relative ? 2 : 0) + (A.loy < 35 ? 1 : 0);
      return `<article class="card sh-officer"><div class="em-pic">${Portrait.svg(A.look)}</div><div>
        <header><div><span class="eyebrow">${esc(Ro.title)}</span><h3>${esc(A.name)}</h3></div><span class="chip ${A.loy < 25 ? 'banned' : hurt ? '' : 'coopted'}">${hurt ? `в лазарете, ${H.hurt[r]} кв.` : A.loy < 25 ? 'ненадёжен' : A.relative ? 'кадет' : 'на посту'}</span></header>
        <p class="muted small">${esc(A.bio)}</p>
        ${UI.meter('Верность', A.loy, A.loy >= 55 ? 'good' : A.loy >= 30 ? 'warn' : 'bad')}
        <p class="muted small">На высадке: ${Object.keys(SK_NAME).map(k => `${SK_NAME[k]} <b>${Math.max(0, sk[k] - pen)}</b>`).join(' · ')}</p>
        <div class="acts">${UI.actBtn(`adv:${r}:act`, { name: Ro.action, cost: Ro.actionDesc, ok: true })}
          ${shBtn(`shb:${r}:talk`, 'Разговор в каюте', 'приказ · верность +', true)}
          ${shBtn(`shb:${r}:praise`, 'Благодарность в журнал', H.markAt.praise === S.turn ? 'в этом квартале уже была' : 'без приказа · остальные завидуют', H.markAt.praise !== S.turn, true)}
          ${shBtn(`shb:${r}:scold`, 'Выговор при всех', H.markAt.scold === S.turn ? 'в этом квартале уже был' : 'без приказа · дисциплина +, верность −', H.markAt.scold !== S.turn, true)}
          ${UI.actBtn(`adv:${r}:gift`, { name: 'Каюта с иллюминатором', cost: '−8 ед. · верность +15', ok: S.treasury >= 8 })}
          ${H.fireAsk === r ? `<button class="btn small danger-o" data-act="adv:${r}:fire" data-free="1" ${!hub ? 'disabled' : ''}>Да, списать<small>пост займёт кадет</small></button>${shBtn(`shb:${r}:fireask`, 'Передумать', '', true, true)}` : shBtn(`shb:${r}:fireask`, 'Списать с корабля', 'без приказа', true, true)}</div></div></article>`; };
    return `<p class="lede">Мостик — это пять офицеров, на которых держится корабль. С ними можно говорить, их можно хвалить и отчитывать, им можно давать поручения. Раз в несколько кварталов кто-то из них попросит слова. Верность ниже 25 кончается мятежом; списанного офицера заменит кадет, преданный и неумелый.</p>
      <div class="sh-bridge">${Object.keys(S.adv).map(card).join('')}</div>`;
  },
});
const _tabBudS = UI.tab_budget;
UI.tab_budget = function () { return isShip() ? UI.shNorms() : _tabBudS.call(UI); };
const _tabAdvS = UI.tab_advisors;
UI.tab_advisors = function () { return isShip() ? UI.shBridge() : _tabAdvS.call(UI); };
const _tabCabS = UI.tab_cabinet;
UI.tab_cabinet = function () {
  const h = _tabCabS.call(UI);
  if (!isShip()) return h;
  const H = Game.sh();
  return h.replace(/У власти ([\d.,]+) г\./, `В кресле $1 г. ${H.loc.state === 'orbit' ? 'На орбите: ' : 'Курс: '}${PLANETS[H.loc.id].name}. Высадок: ${H.done}, открытий: ${H.disc}, нарушений Устава: ${H.viol}.`).replace('Бюджет за квартал', 'Запасы за квартал');
};
const shText = s => (typeof s === 'string' ? s.replace(/млн/g, 'ед.') : s);
const _renderS = UI.render;
UI.render = function () {
  _renderS.call(UI);
  if (!isShip()) return;
  const set = (t, name) => { const b = document.querySelector(`.tabs button[data-tab="${t}"]`); if (b) b.textContent = name; return b; };
  set('cabinet', 'Каюта капитана'); set('factions', 'Экипаж'); set('budget', 'Нормы'); set('decrees', 'Приказы'); set('world', 'Связь'); set('advisors', 'Мостик'); set('log', 'Бортжурнал');
  const H = Game.sh(), ab = document.querySelector('.tabs button[data-tab="away"]');
  if (ab) { ab.textContent = H.loc.state === 'orbit' && !H.loc.done ? 'Высадки ●' : 'Высадки'; ab.classList.toggle('alert', H.loc.state === 'orbit' && !H.loc.done); }
  const root = document.querySelector('#screen-game');
  const LEG = { 'Народ': 'Экипаж', 'Армия': 'Охрана', 'Экономика': 'Корабль', 'Страх': 'Дисциплина' };
  if (root) { const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; while ((n = w.nextNode())) { const t = n.nodeValue.trim(); if (LEG[t]) n.nodeValue = n.nodeValue.replace(t, LEG[t]); else if (n.nodeValue.includes('млн')) n.nodeValue = n.nodeValue.replace(/млн/g, 'ед.'); } }
};
const _modalOpenS = Modal.open;
Modal.open = function (html, ...rest) { return _modalOpenS.call(Modal, isShip() ? shText(html) : html, ...rest); };
const _toastS = UI.toast;
UI.toast = function (text, ...rest) { return _toastS.call(UI, isShip() ? shText(text) : text, ...rest); };
const DIFF_S = { easy: ['Спокойный сектор', 'Три приказа, полный трюм, корабль прямо с верфи.'], normal: ['Дальний поиск', 'Два приказа. Корабль как корабль.'], hard: ['Глухой космос', 'Запасы тают, высадки труднее. Итог ×1,4.'] };
const _renderSetupS = UI.renderSetup;
UI.renderSetup = function () {
  _renderSetupS.call(UI);
  if (!UI.setup || UI.setup.era !== SHIP) return;
  const root = document.querySelector('#screen-setup'), heads = [...root.querySelectorAll('.sec-h')];
  root.querySelector('h1').textContent = 'Сектор 01: корабль исследователей';
  ['Эпоха', '1. Корабль', '2. Как вы стали капитаном', '3. Имя и облик', '4. Сложность'].forEach((n, i) => { if (heads[i]) heads[i].textContent = n; });
  root.querySelector('label[for="setup-title"]').textContent = 'Звание';
  document.querySelector('#btn-begin').textContent = 'Принять командование';
  for (const m of root.querySelectorAll('#setup-regions .pick-meta')) m.textContent = `ЗК «Благое намерение» · ${SH_Y}–${SH_Y + 9} годы`;
  for (const b of root.querySelectorAll('[data-diff]')) { const d = DIFF_S[b.dataset.diff]; if (d) { b.querySelector('.pick-name').textContent = d[0]; b.querySelector('.pick-desc').textContent = d[1]; } }
  const dbg = document.querySelector('#dk-debug'); if (dbg) dbg.hidden = true;
  const st = UI.setup, inp = document.querySelector('#setup-name');
  if (Object.values(SH_NAMES).includes(st.name) && st.name !== SH_NAMES[st.regime]) { st.name = SH_NAMES[st.regime]; if (inp) inp.value = st.name; UI.renderSetupPortrait(); }
};
// высадка играется сразу, сценой: состав группы уже выбран, решение принимается на месте
Game.shLaunch = async function () {
  const H = Game.sh();
  if (S.phase !== 'hub' || H.loc.state !== 'orbit' || H.loc.done || H.busy || !Game.spend()) return;
  H.busy = true;
  const scene = Game.shAwayScene();
  H.loc.done = true; H.done++;
  Game.log(`Высадка: ${PLANETS[H.loc.id].name}. Группу ведёт ${Game.shLeadName(H.team.lead)}.`);
  try { await VN.play(scene); } finally { H.busy = false; }
  Game.save(); UI.render();
};
UI.actionHandlers.push(id => {
  if (!/^sh[natcb]:/.test(id)) return false;
  if (S.phase !== 'hub') return true;
  const p = id.split(':');
  if (p[0] === 'sha') { Game.shLaunch(); return true; }
  const out = p[0] === 'shn' ? Game.shSetNorm(p[1], +p[2]) : p[0] === 'sht' ? Game.shSetTeam(p[1], p[2]) : p[0] === 'shc' ? Game.shCourse(+p[1]) : Game.shBridgeAction(p[1], p[2]);
  if (out) { UI.render(); if (out.text) UI.toast(out.text, out.changes); }
  return true;
});
